function maxAscendingSum(nums) {
  let best = nums[0];
  let current = nums[0];

  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > nums[i - 1]) {
      current += nums[i];
    } else {
      current = nums[i];
    }
    best = Math.max(best, current);
  }
  return best;
}

