function maxAscendingSum(nums) {
  let best = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start; end < nums.length; end++) {
      let ascending = true;
      let total = 0;
      for (let k = start; k <= end; k++) {
        if (k > start && nums[k] <= nums[k - 1]) ascending = false;
        total += nums[k];
      }
      if (ascending && total > best) best = total;
    }
  }
  return best;
}

