function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const nums = [];
  for (let i = 0; i < n; i++) {
    // Sometimes continue an ascending run so long runs appear, otherwise pick freely.
    if (i > 0 && nums[i - 1] < top && rand() < 0.5) nums.push(nums[i - 1] + 1 + Math.floor(rand() * Math.min(3, top - nums[i - 1])));
    else nums.push(1 + Math.floor(rand() * top));
  }
  return [nums];
}
